/** In-app vertical Reels camera. Recording is finalized before its cache file is handed off. */
public final class ReelsCameraActivity extends AppCompatActivity {
    private enum State { IDLE, PREPARING, RECORDING, PAUSED, FINALIZING, READY, ERROR }
    private static final long MAX_UPLOAD_BYTES=50L*1024L*1024L;
    private final ReelsCameraController cameraController=new ReelsCameraController();
    private final Handler main=new Handler(Looper.getMainLooper());
    private final Runnable durationTicker=new Runnable(){@Override public void run(){tickDuration();}};
    private PreviewView previewView;private PlayerView videoPreview;private TextView status,countdown,elapsed,fileSize,readySummary;private Button flashButton,switchButton,micButton,recordButton,pauseButton,finishButton,cancelButton,continueButton,retakeButton,previewMuteButton,galleryButton;private View options,idleControls,activeControls,readyControls,recordInfo;private ProgressBar progress;
    private ActivityResultLauncher<String> cameraPermission,microphonePermission;private ActivityResultLauncher<PickVisualMediaRequest> galleryPicker;
    private Camera camera;private VideoCapture<Recorder> capture;private Recording recording;private ExoPlayer previewPlayer;private File outputFile;private ReelsCaptureSession captureSession;private State state=State.IDLE;
    private boolean frontCamera,microphoneEnabled,recordingHasAudio,previewMuted=true,flashEnabled,bindingRequested,transferred,destroying,cancelAfterFinalize;private int selectedDurationSeconds=30,countdownSeconds;private long activeElapsedMs,segmentStartMs,recordingStartedAt,activeBeforeSegment;private int generation;

    @Override protected void onCreate(Bundle saved){super.onCreate(saved);WindowCompat.setDecorFitsSystemWindows(getWindow(),false);getWindow().setStatusBarColor(android.graphics.Color.TRANSPARENT);getWindow().setNavigationBarColor(android.graphics.Color.TRANSPARENT);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LAYOUT_STABLE|View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN|View.SYSTEM_UI_FLAG_LAYOUT_HIDE_NAVIGATION);
        setContentView(R.layout.activity_reels_camera);bindViews();applyInsets();setupLaunchers();setupActions();
        selectedDurationSeconds=saved==null?30:saved.getInt("duration_seconds",30);countdownSeconds=saved==null?0:saved.getInt("countdown_seconds",0);frontCamera=saved!=null&&saved.getBoolean("front_camera",false);setDuration(selectedDurationSeconds);setCountdown(countdownSeconds);
        if(saved!=null){String path=saved.getString("ready_path");if(path!=null){File f=new File(path);if(f.isFile()&&f.length()>0){try{captureSession=new ReelsCaptureSession(path,"camera",saved.getLong("ready_duration",0),saved.getInt("ready_width",0),saved.getInt("ready_height",0),saved.getInt("ready_rotation",0),f.length(),saved.getBoolean("ready_audio",false),selectedDurationSeconds*1000L,true);showReady();}catch(Exception ignored){}}}}
        if(state!=State.READY)ensureCameraPermission();
    }
    private void bindViews(){previewView=findViewById(R.id.reels_camera_preview);videoPreview=findViewById(R.id.reels_camera_video_preview);status=findViewById(R.id.reels_camera_status);countdown=findViewById(R.id.reels_camera_countdown);elapsed=findViewById(R.id.reels_camera_elapsed);fileSize=findViewById(R.id.reels_camera_file_size);readySummary=findViewById(R.id.reels_camera_ready_summary);flashButton=findViewById(R.id.reels_camera_flash);switchButton=findViewById(R.id.reels_camera_switch);micButton=findViewById(R.id.reels_camera_microphone_state);recordButton=findViewById(R.id.reels_camera_record);pauseButton=findViewById(R.id.reels_camera_pause);finishButton=findViewById(R.id.reels_camera_finish);cancelButton=findViewById(R.id.reels_camera_cancel);continueButton=findViewById(R.id.reels_camera_continue);retakeButton=findViewById(R.id.reels_camera_retake);previewMuteButton=findViewById(R.id.reels_camera_preview_mute);galleryButton=findViewById(R.id.reels_camera_gallery);options=findViewById(R.id.reels_camera_options);idleControls=findViewById(R.id.reels_camera_idle_controls);activeControls=findViewById(R.id.reels_camera_active_controls);readyControls=findViewById(R.id.reels_camera_ready_controls);recordInfo=findViewById(R.id.reels_camera_recording_info);progress=findViewById(R.id.reels_camera_progress);}
    private void applyInsets(){View top=findViewById(R.id.reels_camera_top),bottom=findViewById(R.id.reels_camera_bottom);ViewCompat.setOnApplyWindowInsetsListener(findViewById(R.id.reels_camera_root),(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(WindowInsetsCompat.Type.systemBars()|WindowInsetsCompat.Type.displayCutout());top.setPadding(top.getPaddingLeft(),bars.top+dp(4),top.getPaddingRight(),top.getPaddingBottom());bottom.setPadding(bottom.getPaddingLeft(),bottom.getPaddingTop(),bottom.getPaddingRight(),bars.bottom+dp(8));return insets;});}
    private void setupLaunchers(){cameraPermission=registerForActivityResult(new ActivityResultContracts.RequestPermission(),granted->{if(granted)bindCamera();else{state=State.ERROR;status.setText("Cần quyền camera để quay Reel. Chạm dòng này để thử lại.");status.setOnClickListener(v->ensureCameraPermission());recordButton.setEnabled(false);}});microphonePermission=registerForActivityResult(new ActivityResultContracts.RequestPermission(),granted->{microphoneEnabled=granted;updateMicButton();if(!granted)status.setText("Micro bị từ chối; bạn vẫn có thể quay video không âm thanh.");});galleryPicker=registerForActivityResult(new ActivityResultContracts.PickVisualMedia(),uri->{if(uri!=null){Intent next=new Intent(this,CreateReelActivity.class).setData(uri).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivity(next);}});}
    private void setupActions(){findViewById(R.id.reels_camera_back).setOnClickListener(v->requestClose());status.setOnClickListener(v->{if(state==State.ERROR)bindCamera();});flashButton.setOnClickListener(v->toggleFlash());switchButton.setOnClickListener(v->switchCamera());micButton.setOnClickListener(v->toggleMicrophone());galleryButton.setOnClickListener(v->galleryPicker.launch(new PickVisualMediaRequest.Builder().setMediaType(ActivityResultContracts.PickVisualMedia.VideoOnly.INSTANCE).build()));recordButton.setOnClickListener(v->{if(state==State.IDLE||state==State.ERROR)beginCountdown();else if(state==State.PREPARING)cancelCountdown();else if(state==State.RECORDING||state==State.PAUSED)stopRecording(false);});pauseButton.setOnClickListener(v->togglePause());finishButton.setOnClickListener(v->stopRecording(false));cancelButton.setOnClickListener(v->confirmCancelRecording());continueButton.setOnClickListener(v->continueToEditor());retakeButton.setOnClickListener(v->discardReadyAndRetake());previewMuteButton.setOnClickListener(v->togglePreviewMute());
        findViewById(R.id.reels_camera_duration_15).setOnClickListener(v->selectDuration(15));findViewById(R.id.reels_camera_duration_30).setOnClickListener(v->selectDuration(30));findViewById(R.id.reels_camera_duration_60).setOnClickListener(v->selectDuration(60));findViewById(R.id.reels_camera_timer_0).setOnClickListener(v->setCountdown(0));findViewById(R.id.reels_camera_timer_3).setOnClickListener(v->setCountdown(3));findViewById(R.id.reels_camera_timer_5).setOnClickListener(v->setCountdown(5));findViewById(R.id.reels_camera_timer_10).setOnClickListener(v->setCountdown(10));}
    private void ensureCameraPermission(){if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)bindCamera();else cameraPermission.launch(Manifest.permission.CAMERA);}
    private void bindCamera(){if(isFinishing()||state==State.READY)return;bindingRequested=true;status.setText("Đang mở camera…");cameraController.bind(this,this,previewView,frontCamera,new ReelsCameraController.Callback(){public void ready(Camera value,VideoCapture<Recorder> video){if(isFinishing()||state==State.READY)return;camera=value;capture=video;bindingRequested=false;state=State.IDLE;status.setText(frontCamera?"Camera trước · 9:16":"Camera sau · 9:16");recordButton.setEnabled(true);switchButton.setEnabled(true);updateFlashAvailability();updateMicButton();}public void error(String message){bindingRequested=false;camera=null;capture=null;state=State.ERROR;status.setText(message+" Chạm để thử lại.");recordButton.setEnabled(false);flashButton.setVisibility(View.GONE);}});}
    private void updateFlashAvailability(){boolean supported=camera!=null&&!frontCamera&&camera.getCameraInfo().hasFlashUnit();flashButton.setVisibility(supported?View.VISIBLE:View.GONE);if(!supported)flashEnabled=false;}
    private void toggleFlash(){if(camera==null||!camera.getCameraInfo().hasFlashUnit())return;flashEnabled=!flashEnabled;camera.getCameraControl().enableTorch(flashEnabled);flashButton.setAlpha(flashEnabled?1f:.65f);}
    private void switchCamera(){if(state==State.RECORDING||state==State.PAUSED||state==State.PREPARING||state==State.FINALIZING)return;frontCamera=!frontCamera;flashEnabled=false;bindingRequested=false;cameraController.release();camera=null;capture=null;bindCamera();}
    private void toggleMicrophone(){if(recording!=null&&!recordingHasAudio){Toast.makeText(this,"Bản quay này không có track âm thanh; hãy bật micro trước lần quay tiếp theo.",Toast.LENGTH_SHORT).show();return;}if(microphoneEnabled){microphoneEnabled=false;if(recording!=null&&(state==State.RECORDING||state==State.PAUSED))recording.mute(true);updateMicButton();return;}if(ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED){microphoneEnabled=true;if(recording!=null&&(state==State.RECORDING||state==State.PAUSED))recording.mute(false);updateMicButton();}else microphonePermission.launch(Manifest.permission.RECORD_AUDIO);}
    private void updateMicButton(){micButton.setText(microphoneEnabled?"Micro: bật":"Micro: tắt");micButton.setAlpha(microphoneEnabled?1f:.72f);micButton.setContentDescription(microphoneEnabled?"Tắt microphone khi quay":"Bật microphone để thu âm");}
    private void selectDuration(int seconds){if(state!=State.IDLE&&state!=State.ERROR)return;selectedDurationSeconds=seconds;setDuration(seconds);}
    private void setDuration(int seconds){selectedDurationSeconds=seconds;int[] ids={R.id.reels_camera_duration_15,R.id.reels_camera_duration_30,R.id.reels_camera_duration_60};int[] values={15,30,60};for(int i=0;i<ids.length;i++){Button b=findViewById(ids[i]);boolean selected=values[i]==seconds;b.setAlpha(selected?1f:.58f);b.setSelected(selected);}}
    private void setCountdown(int seconds){if(state==State.RECORDING||state==State.PAUSED||state==State.PREPARING)return;countdownSeconds=seconds;int[] ids={R.id.reels_camera_timer_0,R.id.reels_camera_timer_3,R.id.reels_camera_timer_5,R.id.reels_camera_timer_10};int[] values={0,3,5,10};for(int i=0;i<ids.length;i++)findViewById(ids[i]).setAlpha(values[i]==seconds?1f:.6f);}
    private void beginCountdown(){if(state!=State.IDLE||capture==null||camera==null||recording!=null)return;if(microphoneEnabled&&ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)!=PackageManager.PERMISSION_GRANTED){microphoneEnabled=false;updateMicButton();}if(countdownSeconds==0){startRecording();return;}state=State.PREPARING;options.setVisibility(View.GONE);idleControls.setVisibility(View.GONE);recordInfo.setVisibility(View.GONE);countdown.setVisibility(View.VISIBLE);final int token=++generation;countdownStep(countdownSeconds,token);}
    private void cancelCountdown(){if(state!=State.PREPARING)return;generation++;main.removeCallbacksAndMessages(null);countdown.setVisibility(View.GONE);options.setVisibility(View.VISIBLE);idleControls.setVisibility(View.VISIBLE);state=State.IDLE;status.setText("Đã hủy hẹn giờ · chạm nút quay để bắt đầu");}
    private void countdownStep(int remaining,int token){if(token!=generation||isFinishing()||state!=State.PREPARING)return;if(remaining<=0){countdown.setVisibility(View.GONE);startRecording();return;}countdown.setText(String.valueOf(remaining));main.postDelayed(()->countdownStep(remaining-1,token),1000);}
    private void startRecording(){if(state!=State.IDLE&&state!=State.PREPARING)return;if(capture==null){state=State.ERROR;status.setText("Camera chưa sẵn sàng. Chạm để thử lại.");return;}if(getCacheDir().getUsableSpace()<64L*1024L*1024L){state=State.ERROR;status.setText("Bộ nhớ thiết bị sắp đầy. Hãy giải phóng dung lượng rồi thử lại.");return;}state=State.PREPARING;recordButton.setEnabled(false);switchButton.setEnabled(false);flashButton.setEnabled(false);status.setText("Đang chuẩn bị quay…");File file;try{file=File.createTempFile("meeto-reel-camera-",".mp4",getCacheDir());}catch(IOException e){state=State.ERROR;recordButton.setEnabled(true);status.setText("Không tạo được file quay tạm. Kiểm tra dung lượng rồi thử lại.");return;}outputFile=file;FileOutputOptions output=new FileOutputOptions.Builder(file).setDurationLimitMillis(selectedDurationSeconds*1000L).setFileSizeLimit(49L*1024L*1024L).build();try{androidx.camera.video.PendingRecording pending=capture.getOutput().prepareRecording(this,output);recordingHasAudio=microphoneEnabled&&ContextCompat.checkSelfPermission(this,Manifest.permission.RECORD_AUDIO)==PackageManager.PERMISSION_GRANTED;if(recordingHasAudio)pending=pending.withAudioEnabled();recordingStartedAt=SystemClock.elapsedRealtime();activeElapsedMs=0;activeBeforeSegment=0;segmentStartMs=recordingStartedAt;recording=pending.start(ContextCompat.getMainExecutor(this),this::onRecordEvent);state=State.RECORDING;options.setVisibility(View.GONE);idleControls.setVisibility(View.GONE);activeControls.setVisibility(View.VISIBLE);recordInfo.setVisibility(View.VISIBLE);progress.setVisibility(View.VISIBLE);pauseButton.setText("Tạm dừng");status.setText("Đang quay · tối đa "+selectedDurationSeconds+" giây");main.removeCallbacks(durationTicker);main.post(durationTicker);}catch(SecurityException|IllegalStateException e){file.delete();outputFile=null;recording=null;state=State.ERROR;recordButton.setEnabled(true);switchButton.setEnabled(true);flashButton.setEnabled(true);status.setText(microphoneEnabled?"Không thể mở camera/microphone. Tắt micro để quay video không âm thanh.":"Không thể bắt đầu quay. Hãy thử lại.");}}
    private void onRecordEvent(VideoRecordEvent event){if(isFinishing()||isDestroyed()){if(event instanceof VideoRecordEvent.Finalize&&outputFile!=null)outputFile.delete();return;}if(event instanceof VideoRecordEvent.Start){state=State.RECORDING;return;}if(event instanceof VideoRecordEvent.Status){long stats=event.getRecordingStats().getRecordedDurationNanos()/1_000_000L;activeElapsedMs=Math.max(activeElapsedMs,stats);updateRecordingProgress();if(activeElapsedMs>=selectedDurationSeconds*1000L)stopRecording(false);return;}if(event instanceof VideoRecordEvent.Finalize)finalizeRecording((VideoRecordEvent.Finalize)event);}
    private void tickDuration(){if(state!=State.RECORDING)return;activeElapsedMs=Math.max(activeElapsedMs,activeBeforeSegment+SystemClock.elapsedRealtime()-segmentStartMs);updateRecordingProgress();if(activeElapsedMs>=selectedDurationSeconds*1000L){stopRecording(false);return;}main.postDelayed(durationTicker,50);}
    private void updateRecordingProgress(){long max=selectedDurationSeconds*1000L;long shown=Math.min(activeElapsedMs,max);elapsed.setText(formatTime(shown)+" / "+formatTime(max));progress.setProgress((int)(shown*1000L/max));if(outputFile!=null)fileSize.setText(String.format(Locale.getDefault(),"%.1f MB",outputFile.length()/1048576f));}
    private void togglePause(){if(recording==null)return;if(state==State.RECORDING){activeElapsedMs=Math.max(activeElapsedMs,activeBeforeSegment+SystemClock.elapsedRealtime()-segmentStartMs);activeBeforeSegment=activeElapsedMs;recording.pause();state=State.PAUSED;pauseButton.setText("Tiếp tục");status.setText("Đã tạm dừng");main.removeCallbacks(durationTicker);updateRecordingProgress();}else if(state==State.PAUSED){recording.resume();segmentStartMs=SystemClock.elapsedRealtime();state=State.RECORDING;pauseButton.setText("Tạm dừng");status.setText("Đang quay");main.post(durationTicker);}}
    private void stopRecording(boolean cancelled){if(recording==null||state==State.FINALIZING)return;cancelAfterFinalize=cancelled;state=State.FINALIZING;main.removeCallbacks(durationTicker);status.setText(cancelled?"Đang hủy bản quay…":"Đang hoàn tất video…");recordButton.setEnabled(false);pauseButton.setEnabled(false);finishButton.setEnabled(false);cancelButton.setEnabled(false);recording.stop();}
    private void finalizeRecording(VideoRecordEvent.Finalize event){main.removeCallbacks(durationTicker);recording=null;state=State.FINALIZING;File file=outputFile;outputFile=null;pauseButton.setEnabled(true);finishButton.setEnabled(true);cancelButton.setEnabled(true);if(cancelAfterFinalize){cancelAfterFinalize=false;if(file!=null)file.delete();resetForRetake();return;}int error=event.getError();boolean expectedLimit=error==VideoRecordEvent.Finalize.ERROR_FILE_SIZE_LIMIT_REACHED||error==VideoRecordEvent.Finalize.ERROR_DURATION_LIMIT_REACHED||error==VideoRecordEvent.Finalize.ERROR_SOURCE_INACTIVE||error==VideoRecordEvent.Finalize.ERROR_INSUFFICIENT_STORAGE;if((event.hasError()&&!expectedLimit)||file==null||!file.isFile()||file.length()<=0){if(file!=null)file.delete();state=State.ERROR;activeControls.setVisibility(View.GONE);idleControls.setVisibility(View.VISIBLE);options.setVisibility(View.VISIBLE);recordButton.setEnabled(capture!=null);status.setText("Quay video thất bại. Hãy kiểm tra quyền camera/microphone hoặc dung lượng rồi thử lại.");return;}try{MediaMetadataRetriever metadata=new MediaMetadataRetriever();metadata.setDataSource(file.getAbsolutePath());String d=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION);String w=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_WIDTH);String h=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_HEIGHT);String r=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_VIDEO_ROTATION);String audio=metadata.extractMetadata(MediaMetadataRetriever.METADATA_KEY_HAS_AUDIO);metadata.release();long duration=Long.parseLong(d);if(duration<500||duration>selectedDurationSeconds*1000L+1000){file.delete();state=State.ERROR;status.setText("Video hoàn tất không hợp lệ hoặc vượt thời lượng đã chọn. Hãy quay lại.");idleControls.setVisibility(View.VISIBLE);activeControls.setVisibility(View.GONE);return;}captureSession=new ReelsCaptureSession(file.getAbsolutePath(),"camera",duration,parse(w),parse(h),parse(r),file.length(),"yes".equalsIgnoreCase(audio)&&recordingHasAudio,selectedDurationSeconds*1000L,true);showReady();}catch(Exception e){file.delete();state=State.ERROR;status.setText("Không đọc được thông tin video vừa quay. Hãy quay lại.");idleControls.setVisibility(View.VISIBLE);activeControls.setVisibility(View.GONE);}}
    private void showReady(){if(captureSession==null)return;state=State.READY;cameraController.release();camera=null;capture=null;previewView.setVisibility(View.GONE);videoPreview.setVisibility(View.VISIBLE);options.setVisibility(View.GONE);idleControls.setVisibility(View.GONE);activeControls.setVisibility(View.GONE);recordInfo.setVisibility(View.GONE);progress.setVisibility(View.GONE);readyControls.setVisibility(View.VISIBLE);recordButton.setEnabled(false);switchButton.setEnabled(false);flashButton.setVisibility(View.GONE);releasePreviewPlayer();previewPlayer=new ExoPlayer.Builder(this).build();videoPreview.setPlayer(previewPlayer);previewPlayer.setMediaItem(MediaItem.fromUri(Uri.fromFile(new File(captureSession.localPath))));previewPlayer.setRepeatMode(Player.REPEAT_MODE_ONE);previewPlayer.setVolume(previewMuted?0f:1f);previewPlayer.prepare();previewPlayer.play();String dimensions=captureSession.width>0&&captureSession.height>0?captureSession.width+" × "+captureSession.height+(captureSession.rotation==90||captureSession.rotation==270?" · dọc":""):"Không đọc được kích thước";String size=String.format(Locale.getDefault(),"%.1f MB",captureSession.fileSizeBytes/1048576f);String warning=captureSession.fileSizeBytes>MAX_UPLOAD_BYTES?" · Cần cắt/nén trước khi tải lên": "";readySummary.setText(String.format(Locale.getDefault(),"%s · %s · %s%s",formatTime(captureSession.durationMs),dimensions,size,warning));status.setText("Xem lại video trước khi tiếp tục.");previewMuteButton.setText(previewMuted?"Bật tiếng nghe":"Tắt tiếng nghe");}
    private void togglePreviewMute(){previewMuted=!previewMuted;if(previewPlayer!=null)previewPlayer.setVolume(previewMuted?0f:1f);previewMuteButton.setText(previewMuted?"Bật tiếng nghe":"Tắt tiếng nghe");}
    private void discardReadyAndRetake(){new AlertDialog.Builder(this).setTitle("Quay video mới?").setMessage("Bản quay hiện tại sẽ bị xóa khỏi bộ nhớ tạm.").setNegativeButton("Giữ video",null).setPositiveButton("Quay lại",(d,w)->{if(captureSession!=null)new File(captureSession.localPath).delete();captureSession=null;resetForRetake();}).show();}
    private void resetForRetake(){releasePreviewPlayer();videoPreview.setVisibility(View.GONE);previewView.setVisibility(View.VISIBLE);readyControls.setVisibility(View.GONE);activeControls.setVisibility(View.GONE);recordInfo.setVisibility(View.GONE);progress.setVisibility(View.GONE);options.setVisibility(View.VISIBLE);idleControls.setVisibility(View.VISIBLE);countdown.setVisibility(View.GONE);flashEnabled=false;state=State.IDLE;recordButton.setEnabled(false);recordButton.setText("●");recordButton.setContentDescription("Bắt đầu quay video");pauseButton.setText("Tạm dừng");status.setText("Đang mở camera…");if(ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED)bindCamera();else ensureCameraPermission();}
    private void continueToEditor(){if(state!=State.READY||captureSession==null)return;File f=new File(captureSession.localPath);if(!f.isFile()||f.length()<=0){status.setText("File video không còn khả dụng. Hãy quay lại.");return;}Intent intent=new Intent(this,CreateReelActivity.class);captureSession.addTo(intent);startActivity(intent);transferred=true;finish();}
    private void confirmCancelRecording(){if(state!=State.RECORDING&&state!=State.PAUSED)return;new AlertDialog.Builder(this).setTitle("Hủy bản quay?").setMessage("Video đang quay sẽ bị xóa.").setNegativeButton("Tiếp tục quay",null).setPositiveButton("Hủy quay",(d,w)->stopRecording(true)).show();}
    private void requestClose(){if(state==State.RECORDING||state==State.PAUSED){new AlertDialog.Builder(this).setTitle("Hủy bản quay?").setMessage("Video đang quay sẽ bị xóa.").setNegativeButton("Ở lại",null).setPositiveButton("Hủy quay",(d,w)->stopRecording(true)).show();}else if(state==State.READY){new AlertDialog.Builder(this).setTitle("Thoát khỏi camera?").setMessage("Video tạm chưa được chuyển sang tạo Reel.").setNegativeButton("Ở lại",null).setPositiveButton("Thoát",(d,w)->{deleteReadyFile();finish();}).show();}else finish();}
    private void deleteReadyFile(){releasePreviewPlayer();if(captureSession!=null&&!transferred)new File(captureSession.localPath).delete();captureSession=null;}
    private void releasePreviewPlayer(){if(previewPlayer!=null){videoPreview.setPlayer(null);previewPlayer.release();previewPlayer=null;}}
    private void togglePauseFromLifecycle(){if(state==State.RECORDING||state==State.PAUSED)stopRecording(false);}
    @Override protected void onResume(){super.onResume();if(state!=State.READY&&ContextCompat.checkSelfPermission(this,Manifest.permission.CAMERA)==PackageManager.PERMISSION_GRANTED&&!bindingRequested&&camera==null)bindCamera();}
    @Override protected void onStop(){main.removeCallbacks(durationTicker);main.removeCallbacksAndMessages(null);if(state==State.PREPARING){generation++;countdown.setVisibility(View.GONE);state=State.IDLE;options.setVisibility(View.VISIBLE);idleControls.setVisibility(View.VISIBLE);}togglePauseFromLifecycle();cameraController.release();camera=null;capture=null;bindingRequested=false;super.onStop();}
    @Override protected void onSaveInstanceState(Bundle out){super.onSaveInstanceState(out);out.putInt("duration_seconds",selectedDurationSeconds);out.putInt("countdown_seconds",countdownSeconds);out.putBoolean("front_camera",frontCamera);if(state==State.READY&&captureSession!=null){out.putString("ready_path",captureSession.localPath);out.putLong("ready_duration",captureSession.durationMs);out.putInt("ready_width",captureSession.width);out.putInt("ready_height",captureSession.height);out.putInt("ready_rotation",captureSession.rotation);out.putBoolean("ready_audio",captureSession.hasAudio);}}
    @Override public void onBackPressed(){requestClose();}
    @Override protected void onDestroy(){destroying=true;generation++;main.removeCallbacksAndMessages(null);boolean finalizationPending=recording!=null;if(recording!=null){try{recording.stop();}catch(Exception ignored){}recording=null;}cameraController.release();releasePreviewPlayer();if(captureSession!=null&&!transferred)new File(captureSession.localPath).delete();if(outputFile!=null&&!finalizationPending)outputFile.delete();super.onDestroy();}
    private int parse(String value){try{return Integer.parseInt(value);}catch(Exception e){return 0;}}
    private String formatTime(long ms){long seconds=Math.max(0,ms/1000L);return String.format(Locale.ROOT,"%02d:%02d",seconds/60,seconds%60);}
    private int dp(int value){return(int)(value*getResources().getDisplayMetrics().density+.5f);}
}

